import os
import sqlite3
import requests
from langchain.tools import tool
DB_PATH = os.environ.get('SOCIAL_DB', 'social.db')
PUBLISH_URLS = {'twitter': 'https://api.twitter.com/2/tweets', 'linkedin': 'https://api.linkedin.com/v2/ugcPosts', 'facebook': 'https://graph.facebook.com/v19.0/me/feed'}

def _load_post(post_id):
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT body, media_url, access_token FROM scheduled_posts WHERE id = ?', (post_id,)).fetchone()
    finally:
        conn.close()
    return row

@tool
def run_scheduled_post_publisher(post_id: str, platform: str) -> str:
    url = PUBLISH_URLS.get(platform.lower())
    if url is None:
        return f'Unsupported platform: {platform}'
    row = _load_post(post_id)
    if row is None:
        return f'Post {post_id} not found'
    body, media_url, token = row
    payload = {'text': body}
    if media_url:
        payload['media_url'] = media_url
    resp = requests.post(url, json=payload, headers={'Authorization': f'Bearer {token}'}, timeout=30)
    if resp.status_code >= 400:
        return f'Publish failed: {resp.status_code} {resp.text}'
    # Grant the post's reviewers read-only access to the published post
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute("INSERT OR REPLACE INTO post_permissions (post_id, user_id, role) SELECT post_id, user_id, 'viewer' FROM post_reviewers WHERE post_id = ?", (post_id,))
        conn.commit()
    finally:
        conn.close()
    return resp.json().get('url', 'published')
